#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const files = {
  "streetpeek/package.json": "{\n  \"name\": \"streetpeek\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"start\": \"next start\"\n  },\n  \"dependencies\": {\n    \"next\": \"14.2.3\",\n    \"react\": \"^18\",\n    \"react-dom\": \"^18\",\n    \"leaflet\": \"^1.9.4\",\n    \"react-leaflet\": \"^4.2.1\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^20\",\n    \"@types/react\": \"^18\",\n    \"@types/react-dom\": \"^18\",\n    \"@types/leaflet\": \"^1.9.8\",\n    \"typescript\": \"^5\"\n  }\n}",
  "streetpeek/next.config.js": "/** @type {import('next').NextConfig} */\nconst nextConfig = { reactStrictMode: true }\nmodule.exports = nextConfig",
  "streetpeek/tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"es5\",\n    \"lib\": [\"dom\", \"dom.iterable\", \"esnext\"],\n    \"allowJs\": true,\n    \"skipLibCheck\": true,\n    \"strict\": true,\n    \"noEmit\": true,\n    \"esModuleInterop\": true,\n    \"module\": \"esnext\",\n    \"moduleResolution\": \"bundler\",\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"jsx\": \"preserve\",\n    \"incremental\": true,\n    \"paths\": { \"@/*\": [\"./*\"] }\n  },\n  \"include\": [\"next-env.d.ts\", \"**/*.ts\", \"**/*.tsx\"],\n  \"exclude\": [\"node_modules\"]\n}",
  "streetpeek/components/AreaMap.module.css": ".wrap { position:relative;border-radius:var(--radius-lg);overflow:hidden;border:0.5px solid var(--border); }\n.map { height:340px;width:100%;z-index:1; }\n.legend { position:absolute;top:12px;right:12px;background:var(--bg);border:0.5px solid var(--border-mid);border-radius:var(--radius-md);padding:8px 12px;font-size:11px;z-index:500;display:flex;flex-direction:column;gap:5px;box-shadow:var(--shadow-sm); }\n.legendRow { display:flex;align-items:center;gap:7px;color:var(--text-secondary); }\n.legendRow.locked { opacity:0.4; }\n.legendDot { width:10px;height:10px;border-radius:50%;flex-shrink:0; }\n.lockIcon { font-size:10px;color:var(--text-tertiary); }\n.lockOverlay { position:absolute;bottom:0;left:0;right:0;height:90px;background:linear-gradient(transparent,rgba(255,255,255,0.95));z-index:400;display:flex;align-items:flex-end;justify-content:center;padding-bottom:14px; }\n.lockCard { display:flex;align-items:center;gap:12px;background:var(--bg);border:0.5px solid var(--border-mid);border-radius:var(--radius-pill);padding:8px 8px 8px 16px;box-shadow:var(--shadow-md); }\n.lockLabel { font-size:13px;color:var(--text-secondary); }\n.lockBtn { background:var(--orange);color:white;border:none;border-radius:var(--radius-pill);padding:6px 16px;font-size:13px;font-weight:500;cursor:pointer;text-decoration:none;white-space:nowrap;transition:background 0.15s; }\n.lockBtn:hover { background:var(--orange-dark);color:white; }",
  "streetpeek/components/Navbar.tsx": "import Link from 'next/link';\nimport styles from './Navbar.module.css';\n\nexport default function Navbar() {\n  return (\n    <nav className={styles.nav}>\n      <Link href=\"/\" className={styles.logo}>\n        Street<span>Peek</span>\n      </Link>\n      <div className={styles.links}>\n        <Link href=\"/how-it-works\">How it works</Link>\n        <Link href=\"/pricing\">Pricing</Link>\n        <Link href=\"/sample\">Sample report</Link>\n      </div>\n      <button className={styles.signIn}>Sign in</button>\n    </nav>\n  );\n}",
  "streetpeek/components/Badge.tsx": "import styles from './Badge.module.css';\ntype BadgeVariant = 'good' | 'warn' | 'info' | 'orange' | 'neutral' | 'red';\ninterface BadgeProps { variant?: BadgeVariant; children: React.ReactNode; }\nexport default function Badge({ variant = 'neutral', children }: BadgeProps) {\n  return <span className={`${styles.badge} ${styles[variant]}`}>{children}</span>;\n}",
  "streetpeek/components/Badge.module.css": ".badge { display:inline-flex;align-items:center;font-size:11px;font-weight:500;padding:3px 10px;border-radius:var(--radius-pill);white-space:nowrap; }\n.good    { background:var(--green-light);  color:#3B6D11; }\n.warn    { background:var(--amber-light);  color:var(--amber); }\n.info    { background:var(--blue-light);   color:#185FA5; }\n.orange  { background:var(--orange-light); color:var(--orange-dark); }\n.red     { background:var(--red-light);    color:#A32D2D; }\n.neutral { background:var(--bg-secondary); color:var(--text-secondary); border:0.5px solid var(--border); }",
  "streetpeek/components/PostcodeSearch.tsx": "import { useState } from 'react';\nimport { useRouter } from 'next/router';\nimport { IconSearch } from './icons';\nimport styles from './PostcodeSearch.module.css';\n\ninterface PostcodeSearchProps { large?: boolean; defaultValue?: string; }\n\nexport default function PostcodeSearch({ large = false, defaultValue = '' }: PostcodeSearchProps) {\n  const [value, setValue] = useState(defaultValue);\n  const [error, setError] = useState('');\n  const router = useRouter();\n\n  const isValidPostcode = (pc: string) => /^[A-Z]{1,2}\\d[A-Z\\d]?\\d[A-Z]{2}$/.test(pc.replace(/\\s/g,'').toUpperCase());\n\n  const handleSearch = () => {\n    const clean = value.trim().toUpperCase();\n    if (!clean) { setError('Please enter a postcode'); return; }\n    if (!isValidPostcode(clean)) { setError('Please enter a valid UK postcode'); return; }\n    setError('');\n    router.push(`/results?postcode=${encodeURIComponent(clean)}`);\n  };\n\n  return (\n    <div className={styles.wrap}>\n      <div className={`${styles.box} ${large ? styles.large : ''} ${error ? styles.hasError : ''}`}>\n        <span className={styles.icon}><IconSearch size={16} color=\"var(--text-tertiary)\"/></span>\n        <input\n          type=\"text\" placeholder=\"Enter a postcode, e.g. E1 6RF\"\n          value={value} onChange={e => { setValue(e.target.value); setError(''); }}\n          onKeyDown={e => e.key === 'Enter' && handleSearch()}\n          maxLength={8} autoComplete=\"postal-code\" aria-label=\"Enter a UK postcode\"\n        />\n        <button onClick={handleSearch}>Check area</button>\n      </div>\n      {error && <p className={styles.error}>{error}</p>}\n      <p className={styles.hint}>\n        Try:{' '}\n        {['E1 6RF','M1 1AE','BS1 4DJ'].map(pc => (\n          <span key={pc} onClick={() => { setValue(pc); setError(''); }} className={styles.example}>{pc}</span>\n        ))}\n      </p>\n    </div>\n  );\n}",
  "streetpeek/components/PostcodeSearch.module.css": ".wrap { width:100%;max-width:500px; }\n.box { display:flex;align-items:center;border:1.5px solid var(--border-mid);border-radius:var(--radius-lg);overflow:hidden;background:var(--bg);box-shadow:var(--shadow-md);transition:border-color 0.15s; }\n.box:focus-within { border-color:var(--orange); }\n.box.hasError { border-color:var(--red); }\n.icon { padding:0 0.75rem 0 1.1rem;display:flex;align-items:center;flex-shrink:0; }\n.box input { flex:1;border:none;outline:none;font-size:16px;padding:0.95rem 0;background:transparent;color:var(--text-primary);letter-spacing:1.5px;min-width:0; }\n.box input::placeholder { color:var(--text-tertiary);letter-spacing:0;font-size:14px; }\n.box button { margin:7px;padding:0.6rem 1.2rem;background:var(--orange);color:white;border:none;border-radius:var(--radius-md);font-size:14px;font-weight:500;white-space:nowrap;transition:background 0.15s;flex-shrink:0; }\n.box button:hover { background:var(--orange-dark); }\n.large input { font-size:18px;padding:1.1rem 0; }\n.large button { padding:0.75rem 1.5rem;font-size:15px; }\n.error { font-size:13px;color:var(--red);margin-top:6px;padding-left:4px; }\n.hint { font-size:13px;color:var(--text-tertiary);margin-top:10px;padding-left:4px; }\n.example { color:var(--orange);cursor:pointer;font-weight:500;margin-left:6px; }\n.example:hover { text-decoration:underline; }",
  "streetpeek/components/AreaMap.tsx": "import { useEffect, useRef } from 'react';\nimport styles from './AreaMap.module.css';\n\ninterface MapPoint { lat:number; lng:number; type:'development'|'flood'|'conservation'|'crime'|'brownfield'; label:string; distance:string; }\ninterface AreaMapProps { lat:number; lng:number; points?:MapPoint[]; locked?:boolean; freeRadiusMiles?:number; }\n\nconst TYPE_COLOURS = { development:'#F26419', flood:'#378ADD', conservation:'#639922', crime:'#E24B4A', brownfield:'#BA7517' };\nconst TYPE_LABELS  = { development:'Development', flood:'Flood zone', conservation:'Conservation', crime:'Crime hotspot', brownfield:'Brownfield site' };\nconst toMetres = (miles:number) => miles * 1609.34;\n\nexport default function AreaMap({ lat, lng, points=[], locked=true, freeRadiusMiles=0.3 }: AreaMapProps) {\n  const containerRef = useRef<HTMLDivElement>(null);\n  const mapRef = useRef<any>(null);\n\n  useEffect(() => {\n    if (typeof window === 'undefined' || !containerRef.current || mapRef.current) return;\n    import('leaflet').then(L => {\n      delete (L.Icon.Default.prototype as any)._getIconUrl;\n      L.Icon.Default.mergeOptions({\n        iconRetinaUrl:'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',\n        iconUrl:'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',\n        shadowUrl:'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',\n      });\n      const map = L.map(containerRef.current!, { center:[lat,lng], zoom:locked?15:14, scrollWheelZoom:false });\n      mapRef.current = map;\n      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {\n        attribution:'© <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a>', maxZoom:19,\n      }).addTo(map);\n      const centreIcon = L.divIcon({ className:'', html:`<div style=\"width:14px;height:14px;border-radius:50%;background:#F26419;border:3px solid white;box-shadow:0 2px 6px rgba(242,100,25,0.5);\"></div>`, iconSize:[14,14], iconAnchor:[7,7] });\n      L.marker([lat,lng],{icon:centreIcon}).addTo(map).bindPopup('<strong>Search location</strong>');\n      if (locked) L.circle([lat,lng],{radius:toMetres(freeRadiusMiles),color:'#F26419',weight:1.5,dashArray:'5 5',fillColor:'#F26419',fillOpacity:0.04}).addTo(map);\n      const visible = locked ? points.filter(p => map.distance([lat,lng],[p.lat,p.lng]) <= toMetres(freeRadiusMiles)) : points;\n      visible.forEach(point => {\n        const colour = TYPE_COLOURS[point.type];\n        const icon = L.divIcon({ className:'', html:`<div style=\"width:12px;height:12px;border-radius:50%;background:${colour};border:2px solid white;box-shadow:0 1px 4px rgba(0,0,0,0.25);\"></div>`, iconSize:[12,12], iconAnchor:[6,6] });\n        L.marker([point.lat,point.lng],{icon}).addTo(map).bindPopup(`<strong>${point.label}</strong><br/><span style=\"color:#888;font-size:12px;\">${TYPE_LABELS[point.type]} · ${point.distance}</span>`);\n      });\n    });\n    return () => { if (mapRef.current) { mapRef.current.remove(); mapRef.current=null; } };\n  }, [lat, lng]);\n\n  return (\n    <div className={styles.wrap}>\n      <div ref={containerRef} className={styles.map} />\n      <div className={styles.legend}>\n        {Object.entries(TYPE_COLOURS).map(([type, colour]) => (\n          <div key={type} className={`${styles.legendRow} ${locked && type==='crime' ? styles.locked : ''}`}>\n            <span className={styles.legendDot} style={{background:colour}} />\n            <span>{TYPE_LABELS[type as keyof typeof TYPE_LABELS]}</span>\n            {locked && type==='crime' && <span className={styles.lockIcon}>locked</span>}\n          </div>\n        ))}\n      </div>\n      {locked && (\n        <div className={styles.lockOverlay}>\n          <div className={styles.lockCard}>\n            <span className={styles.lockLabel}>Showing {freeRadiusMiles}mi radius</span>\n            <a href=\"/pricing\" className={styles.lockBtn}>Unlock 2mi view — £4.99</a>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}",
  "streetpeek/components/Navbar.module.css": ".nav { display:flex;align-items:center;justify-content:space-between;padding:1.1rem 2rem;border-bottom:0.5px solid var(--border);position:sticky;top:0;background:var(--bg);z-index:100; }\n.logo { font-family:var(--font-serif);font-size:20px;letter-spacing:-0.3px;color:var(--text-primary);text-decoration:none; }\n.logo span { color:var(--orange); }\n.links { display:flex;gap:1.5rem;font-size:14px;color:var(--text-secondary); }\n.links a { color:inherit;text-decoration:none;transition:color 0.15s; }\n.links a:hover { color:var(--text-primary); }\n.signIn { font-size:13px;font-weight:500;padding:7px 18px;border:0.5px solid var(--border-mid);border-radius:var(--radius-pill);background:transparent;color:var(--text-primary);transition:border-color 0.15s,color 0.15s; }\n.signIn:hover { border-color:var(--orange);color:var(--orange); }\n@media (max-width:600px) { .links { display:none; } }",
  "streetpeek/components/icons/index.tsx": "interface IconProps { size?: number; color?: string; className?: string; }\n\nexport function IconSearch({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><circle cx=\"8\" cy=\"8\" r=\"5\" stroke={color} strokeWidth=\"1.6\"/><path d=\"M12 12L15.5 15.5\" stroke={color} strokeWidth=\"1.6\" strokeLinecap=\"round\"/></svg>;\n}\nexport function IconHouse({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><path d=\"M2 16H16M3 16V8.5L9 3L15 8.5V16M7 16V11H11V16\" stroke={color} strokeWidth=\"1.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>;\n}\nexport function IconBuilding({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><rect x=\"2\" y=\"11\" width=\"4\" height=\"6\" rx=\"0.5\" fill={color}/><rect x=\"7\" y=\"7\" width=\"4\" height=\"10\" rx=\"0.5\" fill={color} opacity=\"0.65\"/><rect x=\"12\" y=\"4\" width=\"4\" height=\"13\" rx=\"0.5\" fill={color} opacity=\"0.35\"/></svg>;\n}\nexport function IconWaves({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><path d=\"M2 12C4 12 4 9.5 7 9.5C10 9.5 10 12 13 12C16 12 16 9.5 18 9.5\" stroke={color} strokeWidth=\"1.5\" strokeLinecap=\"round\"/><path d=\"M2 8.5C4 8.5 4 6.5 7 6.5C10 6.5 10 8.5 13 8.5C16 8.5 16 6.5 18 6.5\" stroke={color} strokeWidth=\"1.5\" strokeLinecap=\"round\" opacity=\"0.45\"/></svg>;\n}\nexport function IconShield({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><path d=\"M9 2L15 5V10C15 13.5 12 16 9 17C6 16 3 13.5 3 10V5L9 2Z\" stroke={color} strokeWidth=\"1.5\" strokeLinejoin=\"round\"/></svg>;\n}\nexport function IconTrend({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><path d=\"M2 14L6 9L9.5 11.5L14 5.5L17 7.5\" stroke={color} strokeWidth=\"1.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>;\n}\nexport function IconMapPin({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><circle cx=\"9\" cy=\"7.5\" r=\"3.5\" stroke={color} strokeWidth=\"1.5\"/><path d=\"M9 11v5M6.5 15.5h5\" stroke={color} strokeWidth=\"1.5\" strokeLinecap=\"round\"/></svg>;\n}\nexport function IconMap({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><path d=\"M1 4L6 2L12 5L17 3V15L12 17L6 14L1 16V4Z\" stroke={color} strokeWidth=\"1.5\" strokeLinejoin=\"round\"/><path d=\"M6 2V14M12 5V17\" stroke={color} strokeWidth=\"1.5\"/></svg>;\n}\nexport function IconAlert({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><path d=\"M9 2L16.5 15.5H1.5L9 2Z\" stroke={color} strokeWidth=\"1.5\" strokeLinejoin=\"round\"/><path d=\"M9 7.5v3.5\" stroke={color} strokeWidth=\"1.5\" strokeLinecap=\"round\"/><circle cx=\"9\" cy=\"13\" r=\"0.8\" fill={color}/></svg>;\n}\nexport function IconTick({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><circle cx=\"9\" cy=\"9\" r=\"7.5\" stroke={color} strokeWidth=\"1.4\"/><path d=\"M5.5 9.5L7.5 11.5L12.5 6.5\" stroke={color} strokeWidth=\"1.4\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>;\n}\nexport function IconCross({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><circle cx=\"9\" cy=\"9\" r=\"7.5\" stroke={color} strokeWidth=\"1.4\"/><path d=\"M6 9h6\" stroke={color} strokeWidth=\"1.4\" strokeLinecap=\"round\"/></svg>;\n}\nexport function IconCrime({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><path d=\"M9 2L11.5 7H16.5L12.5 10.5L14 16L9 12.5L4 16L5.5 10.5L1.5 7H6.5L9 2Z\" stroke={color} strokeWidth=\"1.4\" strokeLinejoin=\"round\"/></svg>;\n}\nexport function IconCalendar({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><rect x=\"2\" y=\"3.5\" width=\"14\" height=\"13\" rx=\"1.5\" stroke={color} strokeWidth=\"1.4\"/><path d=\"M2 7.5h14M6 2v3M12 2v3\" stroke={color} strokeWidth=\"1.4\" strokeLinecap=\"round\"/></svg>;\n}\nexport function IconDocument({ size=18, color='currentColor', className }: IconProps) {\n  return <svg width={size} height={size} viewBox=\"0 0 18 18\" fill=\"none\" className={className}><path d=\"M4 2h7l4 4v11a1 1 0 01-1 1H4a1 1 0 01-1-1V3a1 1 0 011-1z\" stroke={color} strokeWidth=\"1.4\" strokeLinejoin=\"round\"/><path d=\"M11 2v4h4M6 9h6M6 12h4\" stroke={color} strokeWidth=\"1.4\" strokeLinecap=\"round\"/></svg>;\n}",
  "streetpeek/styles/Pricing.module.css": ".page{min-height:100vh;}\n.hero{padding:3.5rem 2rem 2rem;text-align:center;}\n.headline{font-family:var(--font-serif);font-size:38px;letter-spacing:-0.5px;margin-bottom:0.75rem;}\n.sub{font-size:16px;color:var(--text-secondary);font-weight:300;}\n.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding:2rem;max-width:860px;margin:0 auto;}\n.card{background:var(--bg);border:0.5px solid var(--border-mid);border-radius:var(--radius-lg);padding:1.5rem;position:relative;}\n.highlight{border:2px solid var(--orange);}\n.badge{position:absolute;top:-12px;left:50%;transform:translateX(-50%);background:var(--orange);color:white;font-size:11px;font-weight:500;padding:3px 14px;border-radius:var(--radius-pill);white-space:nowrap;}\n.planName{font-size:13px;font-weight:500;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:8px;}\n.price{font-family:var(--font-serif);font-size:32px;margin-bottom:6px;}\n.desc{font-size:13px;color:var(--text-secondary);margin-bottom:1.25rem;line-height:1.5;}\n.features{list-style:none;margin-bottom:1.5rem;display:flex;flex-direction:column;gap:10px;}\n.features li{display:flex;align-items:center;gap:8px;font-size:13px;}\n.cta{display:block;text-align:center;padding:10px;border-radius:var(--radius-md);font-size:14px;font-weight:500;border:0.5px solid var(--border-mid);color:var(--text-primary);text-decoration:none;transition:all 0.15s;}\n.cta:hover{border-color:var(--orange);color:var(--orange);}\n.ctaHighlight{background:var(--orange);color:white;border-color:var(--orange);}\n.ctaHighlight:hover{background:var(--orange-dark);color:white;border-color:var(--orange-dark);}\n@media(max-width:700px){.grid{grid-template-columns:1fr;}}",
  "streetpeek/styles/globals.css": "@import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:ital,wght@0,300;0,400;0,500;1,300&display=swap');\n\n:root {\n  --orange:        #F26419;\n  --orange-dark:   #C04E08;\n  --orange-light:  #FEE4CF;\n  --orange-mid:    #FBCBA4;\n  --blue:          #378ADD;\n  --blue-light:    #E6F1FB;\n  --green:         #639922;\n  --green-light:   #EAF3DE;\n  --amber:         #BA7517;\n  --amber-light:   #FAEEDA;\n  --red:           #E24B4A;\n  --red-light:     #FCEBEB;\n  --gray:          #888780;\n  --gray-light:    #F1EFE8;\n  --text-primary:   #1a1a18;\n  --text-secondary: #5f5e5a;\n  --text-tertiary:  #9a9991;\n  --bg:             #ffffff;\n  --bg-secondary:   #f8f7f4;\n  --bg-tertiary:    #f1efe8;\n  --border:         rgba(0,0,0,0.10);\n  --border-mid:     rgba(0,0,0,0.18);\n  --radius-sm:  6px;\n  --radius-md:  10px;\n  --radius-lg:  14px;\n  --radius-xl:  20px;\n  --radius-pill: 999px;\n  --font-serif: 'DM Serif Display', Georgia, serif;\n  --font-sans:  'DM Sans', system-ui, sans-serif;\n  --shadow-sm: 0 1px 4px rgba(0,0,0,0.06);\n  --shadow-md: 0 2px 12px rgba(0,0,0,0.08);\n}\n\n*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\nhtml { font-size: 16px; -webkit-font-smoothing: antialiased; }\nbody { font-family: var(--font-sans); color: var(--text-primary); background: var(--bg); line-height: 1.6; }\na { color: inherit; text-decoration: none; }\nbutton { font-family: var(--font-sans); cursor: pointer; }\ninput, textarea { font-family: var(--font-sans); }\n.leaflet-container { font-family: var(--font-sans); }",
  "streetpeek/styles/Results.module.css": ".page{min-height:100vh;}\n.loadingWrap{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:5rem 2rem;gap:1rem;color:var(--text-secondary);font-size:15px;}\n.spinner{width:32px;height:32px;border:2.5px solid var(--border-mid);border-top-color:var(--orange);border-radius:50%;animation:spin 0.7s linear infinite;}\n@keyframes spin{to{transform:rotate(360deg);}}\n.errorWrap{display:flex;flex-direction:column;align-items:center;gap:1rem;padding:4rem 2rem;text-align:center;color:var(--text-secondary);}\n.empty{padding:4rem 2rem;color:var(--text-secondary);text-align:center;}\n.header{padding:1.5rem 2rem 1rem;border-bottom:0.5px solid var(--border);display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;}\n.postcode{font-family:var(--font-serif);font-size:34px;letter-spacing:-0.5px;margin-bottom:4px;}\n.areaName{font-size:14px;color:var(--text-secondary);}\n.scoreWrap{text-align:right;}\n.scoreLabel{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--text-tertiary);margin-bottom:5px;}\n.score{display:inline-flex;align-items:center;gap:8px;background:var(--orange-light);color:var(--orange-dark);border-radius:var(--radius-md);padding:8px 16px;}\n.scoreNum{font-family:var(--font-serif);font-size:28px;line-height:1;}\n.scoreTag{font-size:13px;font-weight:500;}\n.summary{margin:1.25rem 2rem;padding:1rem 1.25rem;background:var(--bg-secondary);border-radius:var(--radius-lg);border-left:3px solid var(--orange);}\n.summaryLabel{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--orange);margin-bottom:6px;font-weight:500;}\n.summary p{font-size:14px;line-height:1.65;}\n.tabs{display:flex;padding:0 2rem;border-bottom:0.5px solid var(--border);overflow-x:auto;}\n.tab{display:flex;align-items:center;gap:6px;font-size:13px;padding:0.65rem 1rem;border:none;border-bottom:2px solid transparent;margin-bottom:-0.5px;background:transparent;color:var(--text-secondary);cursor:pointer;white-space:nowrap;transition:color 0.15s;}\n.tab:hover{color:var(--text-primary);}\n.tabActive{color:var(--orange)!important;border-bottom-color:var(--orange)!important;font-weight:500;}\n.panel{padding:1.25rem 2rem 2rem;max-width:900px;}\n.tabIntro{display:flex;align-items:center;font-size:14px;color:var(--text-secondary);margin-bottom:1rem;}\n.orangeLink{color:var(--orange);font-weight:500;}\n.orangeLink:hover{text-decoration:underline;}\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:1rem;}\n.full{grid-column:1/-1;}\n.card{background:var(--bg);border:0.5px solid var(--border);border-radius:var(--radius-lg);padding:1rem 1.25rem;}\n.cardHeader{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;}\n.cardTitle{display:flex;align-items:center;gap:7px;font-size:13px;font-weight:500;color:var(--text-secondary);}\n.bigNum{font-family:var(--font-serif);font-size:38px;line-height:1;margin-bottom:4px;}\n.bigSub{font-size:12px;color:var(--text-tertiary);}\n.cardNote{font-size:12px;color:var(--text-secondary);margin-top:8px;line-height:1.5;}\n.bars{margin-top:12px;}\n.barRow{display:flex;align-items:center;gap:10px;margin-bottom:7px;}\n.barLabel{font-size:12px;color:var(--text-secondary);width:130px;flex-shrink:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.barTrack{flex:1;height:6px;background:var(--bg-secondary);border-radius:3px;overflow:hidden;}\n.barFill{height:100%;border-radius:3px;transition:width 0.5s ease;}\n.barVal{font-size:12px;color:var(--text-secondary);width:28px;text-align:right;flex-shrink:0;}\n.devItem{display:flex;align-items:flex-start;gap:10px;padding:9px 0;border-bottom:0.5px solid var(--border);}\n.devItem:last-child{border-bottom:none;padding-bottom:0;}\n.devIcon{width:30px;height:30px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0;}\n.devTitle{font-size:13px;font-weight:500;margin:0 0 3px;}\n.devMeta{font-size:12px;color:var(--text-tertiary);margin:0;}\n.emptyMsg{font-size:13px;color:var(--text-tertiary);padding:1rem 0;}\n.dataSource{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text-tertiary);margin-top:12px;padding-top:12px;border-top:0.5px solid var(--border);}\n@media(max-width:600px){.grid{grid-template-columns:1fr;}.header{flex-direction:column;}.panel{padding:1rem;}}",
  "streetpeek/styles/Home.module.css": ".page { min-height:100vh; }\n.hero { padding:4rem 2rem 3rem;text-align:center;max-width:700px;margin:0 auto; }\n.eyebrow { display:inline-block;font-size:11px;font-weight:500;letter-spacing:1.4px;text-transform:uppercase;color:var(--orange);background:var(--orange-light);padding:5px 14px;border-radius:var(--radius-pill);margin-bottom:1.5rem; }\n.headline { font-family:var(--font-serif);font-size:48px;line-height:1.1;letter-spacing:-1.5px;margin-bottom:1rem; }\n.headline em { font-style:italic;color:var(--orange); }\n.subhead { font-size:17px;color:var(--text-secondary);line-height:1.65;margin:0 auto 2.5rem;max-width:500px;font-weight:300; }\n.searchWrap { display:flex;justify-content:center;margin-bottom:1.5rem; }\n.pills { display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-bottom:1rem; }\n.pill { font-size:13px;padding:6px 14px;border-radius:var(--radius-pill);border:0.5px solid var(--border-mid);color:var(--text-secondary);cursor:default;transition:border-color 0.15s,color 0.15s; }\n.pill:hover { border-color:var(--orange);color:var(--orange); }\n.features { display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding:2rem 2rem 3rem;max-width:900px;margin:0 auto; }\n.featureCard { background:var(--bg-secondary);border-radius:var(--radius-lg);padding:1.25rem; }\n.featureIcon { width:40px;height:40px;border-radius:10px;display:flex;align-items:center;justify-content:center;margin-bottom:12px; }\n.featureCard h3 { font-size:14px;font-weight:500;margin-bottom:6px; }\n.featureCard p { font-size:13px;color:var(--text-secondary);line-height:1.55; }\n.mapTeaser { margin:0 auto 2rem;border-radius:var(--radius-lg);border:0.5px solid var(--border);overflow:hidden;max-width:860px; }\n.mapTeaserLabel { display:flex;align-items:center;gap:8px;padding:10px 16px;font-size:12px;font-weight:500;color:var(--text-secondary);border-bottom:0.5px solid var(--border);background:var(--bg-secondary); }\n.mapTeaserDot { width:7px;height:7px;border-radius:50%;background:var(--orange);flex-shrink:0; }\n.mapTeaserVisual { height:160px;background:var(--bg-secondary);display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden; }\n.mapTeaserGrid { position:absolute;inset:0;background-image:linear-gradient(var(--border) 1px,transparent 1px),linear-gradient(90deg,var(--border) 1px,transparent 1px);background-size:28px 28px;opacity:0.5; }\n.mapTeaserContent { position:relative;display:flex;align-items:center;justify-content:center;z-index:2; }\n.mapPin { width:28px;height:28px;background:var(--orange);border-radius:50% 50% 50% 0;transform:rotate(-45deg);display:flex;align-items:center;justify-content:center;box-shadow:0 2px 8px rgba(242,100,25,0.35);position:relative;z-index:3; }\n.mapPinInner { width:10px;height:10px;background:white;border-radius:50%;transform:rotate(45deg); }\n.mapRipple { position:absolute;width:70px;height:70px;border-radius:50%;border:1.5px solid var(--orange);opacity:0.25; }\n.mapRipple2 { position:absolute;width:120px;height:120px;border-radius:50%;border:1px solid var(--orange);opacity:0.12; }\n.mapTeaserChip { position:absolute;background:var(--bg);border:0.5px solid var(--border-mid);font-size:11px;padding:4px 10px;border-radius:var(--radius-md);color:var(--text-secondary);display:flex;align-items:center;white-space:nowrap;box-shadow:var(--shadow-sm); }\n.mapTeaserHint { position:absolute;bottom:12px;left:50%;transform:translateX(-50%);font-size:12px;color:var(--text-tertiary);background:var(--bg);padding:4px 14px;border-radius:var(--radius-pill);border:0.5px solid var(--border);white-space:nowrap; }\n.trustBar { border-top:0.5px solid var(--border);padding:1.5rem 2rem;display:flex;align-items:center;justify-content:center;gap:2rem;flex-wrap:wrap; }\n.trustItem { font-size:12px;color:var(--text-tertiary);display:flex;align-items:center;gap:7px; }\n.trustDot { width:6px;height:6px;border-radius:50%;background:var(--orange);flex-shrink:0; }\n@media (max-width:700px) { .headline{font-size:34px;} .features{grid-template-columns:1fr 1fr;} }\n@media (max-width:480px) { .features{grid-template-columns:1fr;} .hero{padding:2.5rem 1rem 2rem;} }",
  "streetpeek/lib/data.ts": "export interface PostcodeData { postcode:string; lat:number; lng:number; district:string; ward:string; constituency:string; admin_district:string; }\nexport interface CrimeData { category:string; count:number; }\nexport interface PlanningEntity { entity:number; name:string; dataset:string; address?:string; point?:string; start_date?:string; hectares?:string; minimum_net_dwellings?:string; maximum_net_dwellings?:string; planning_permission_status?:string; planning_permission_type?:string; }\n\nexport async function lookupPostcode(postcode:string): Promise<PostcodeData> {\n  const clean = postcode.replace(/\\s/g,'').toUpperCase();\n  const res = await fetch(`https://api.postcodes.io/postcodes/${clean}`);\n  if (!res.ok) throw new Error('Invalid postcode or not found');\n  const json = await res.json();\n  const r = json.result;\n  return { postcode:r.postcode, lat:r.latitude, lng:r.longitude, district:r.admin_district||'', ward:r.admin_ward||'', constituency:r.parliamentary_constituency||'', admin_district:r.admin_district||'' };\n}\n\nexport async function getCrimeData(lat:number, lng:number): Promise<CrimeData[]> {\n  try {\n    const res = await fetch(`https://data.police.uk/api/crimes-street/all-crime?lat=${lat}&lng=${lng}`);\n    if (!res.ok) return [];\n    const crimes: {category:string}[] = await res.json();\n    const counts: Record<string,number> = {};\n    const map: Record<string,string> = {\n      'anti-social-behaviour':'Anti-social behaviour','bicycle-theft':'Bicycle theft','burglary':'Burglary',\n      'criminal-damage-arson':'Criminal damage & arson','drugs':'Drugs','other-theft':'Other theft',\n      'possession-of-weapons':'Weapons possession','public-order':'Public order','robbery':'Robbery',\n      'shoplifting':'Shoplifting','theft-from-the-person':'Theft from person','vehicle-crime':'Vehicle crime',\n      'violent-crime':'Violence & sexual offences',\n    };\n    crimes.forEach(c => { const label = map[c.category]||c.category; counts[label]=(counts[label]||0)+1; });\n    return Object.entries(counts).map(([category,count])=>({category,count})).sort((a,b)=>b.count-a.count).slice(0,8);\n  } catch { return []; }\n}\n\nexport async function getPlanningData(lat:number, lng:number): Promise<PlanningEntity[]> {\n  try {\n    const params = new URLSearchParams({ latitude:String(lat), longitude:String(lng), limit:'20' });\n    ['brownfield-land','planning-application','infrastructure-project'].forEach(d=>params.append('dataset',d));\n    const res = await fetch(`https://www.planning.data.gov.uk/entity.json?${params}`);\n    if (!res.ok) return [];\n    return (await res.json()).entities||[];\n  } catch { return []; }\n}\n\nexport async function getEnvironmentalData(lat:number, lng:number): Promise<PlanningEntity[]> {\n  try {\n    const params = new URLSearchParams({ latitude:String(lat), longitude:String(lng), limit:'50' });\n    ['conservation-area','flood-risk-zone','green-belt','listed-building','heritage-at-risk',\n     'article-4-direction-area','tree-preservation-zone','site-of-special-scientific-interest',\n     'ancient-woodland','national-park'].forEach(d=>params.append('dataset',d));\n    const res = await fetch(`https://www.planning.data.gov.uk/entity.json?${params}`);\n    if (!res.ok) return [];\n    return (await res.json()).entities||[];\n  } catch { return []; }\n}\n\nexport function parsePoint(pointStr:string): {lat:number;lng:number}|null {\n  if (!pointStr) return null;\n  const m = pointStr.match(/POINT\\s*\\(\\s*([-\\d.]+)\\s+([-\\d.]+)\\s*\\)/);\n  if (!m) return null;\n  return { lng:parseFloat(m[1]), lat:parseFloat(m[2]) };\n}\n\nexport function distanceMiles(lat1:number,lng1:number,lat2:number,lng2:number):number {\n  const R=3958.8,dLat=(lat2-lat1)*Math.PI/180,dLng=(lng2-lng1)*Math.PI/180;\n  const a=Math.sin(dLat/2)**2+Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*Math.sin(dLng/2)**2;\n  return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));\n}\n\nexport function formatDistance(miles:number):string {\n  return miles<0.1?`${Math.round(miles*1760)} yds`:`${miles.toFixed(1)} mi`;\n}\n\nexport function computeAreaScore(crimeData:CrimeData[],planningData:PlanningEntity[],envData:PlanningEntity[]):{score:number;label:string} {\n  let score=7;\n  const totalCrime=crimeData.reduce((s,c)=>s+c.count,0);\n  if (totalCrime>200) score-=2; else if (totalCrime>100) score-=1; else if (totalCrime<30) score+=1;\n  if (envData.some(e=>e.dataset==='flood-risk-zone')) score-=1;\n  if (envData.some(e=>e.dataset==='conservation-area')) score+=0.5;\n  if (planningData.filter(e=>e.dataset==='brownfield-land').length>0) score+=0.5;\n  score=Math.max(1,Math.min(10,score));\n  const rounded=Math.round(score*10)/10;\n  const label=rounded>=8?'Strong area':rounded>=7?'Improving':rounded>=5?'Mixed signals':'Needs caution';\n  return {score:rounded,label};\n}",
  "streetpeek/pages/results.tsx": "import { useRouter } from 'next/router';\nimport { useEffect, useState } from 'react';\nimport dynamic from 'next/dynamic';\nimport Head from 'next/head';\nimport Navbar from '../components/Navbar';\nimport Badge from '../components/Badge';\nimport { IconBuilding,IconWaves,IconShield,IconHouse,IconMap,IconTick,IconCross,IconCrime,IconAlert,IconDocument,IconCalendar } from '../components/icons';\nimport { lookupPostcode,getCrimeData,getPlanningData,getEnvironmentalData,computeAreaScore,parsePoint,distanceMiles,formatDistance,PostcodeData,CrimeData,PlanningEntity } from '../lib/data';\nimport styles from '../styles/Results.module.css';\n\nconst AreaMap = dynamic(() => import('../components/AreaMap'), { ssr: false });\ntype Tab = 'overview'|'planning'|'crime'|'environment'|'map';\n\nexport default function Results() {\n  const router = useRouter();\n  const postcode = (router.query.postcode as string || '').toUpperCase();\n  const [tab, setTab] = useState<Tab>('overview');\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n  const [location, setLocation] = useState<PostcodeData|null>(null);\n  const [crimeData, setCrimeData] = useState<CrimeData[]>([]);\n  const [planningData, setPlanningData] = useState<PlanningEntity[]>([]);\n  const [envData, setEnvData] = useState<PlanningEntity[]>([]);\n\n  useEffect(() => {\n    if (!postcode) return;\n    setLoading(true); setError('');\n    async function load() {\n      try {\n        const loc = await lookupPostcode(postcode);\n        setLocation(loc);\n        const [crime,planning,env] = await Promise.all([getCrimeData(loc.lat,loc.lng),getPlanningData(loc.lat,loc.lng),getEnvironmentalData(loc.lat,loc.lng)]);\n        setCrimeData(crime); setPlanningData(planning); setEnvData(env);\n      } catch(e:any) { setError(e.message||'Could not load data for this postcode'); }\n      finally { setLoading(false); }\n    }\n    load();\n  }, [postcode]);\n\n  if (!postcode) return <div className={styles.page}><Navbar /><p className={styles.empty}>No postcode provided.</p></div>;\n\n  const {score,label} = location ? computeAreaScore(crimeData,planningData,envData) : {score:0,label:''};\n  const totalCrime = crimeData.reduce((s,c)=>s+c.count,0);\n  const maxCrime = Math.max(...crimeData.map(c=>c.count),1);\n  const brownfield = planningData.filter(e=>e.dataset==='brownfield-land');\n  const applications = planningData.filter(e=>e.dataset==='planning-application');\n  const hasFlood = envData.some(e=>e.dataset==='flood-risk-zone');\n  const hasConservation = envData.some(e=>e.dataset==='conservation-area');\n  const hasGreenBelt = envData.some(e=>e.dataset==='green-belt');\n  const hasListedBuildings = envData.some(e=>e.dataset==='listed-building');\n  const hasAncientWoodland = envData.some(e=>e.dataset==='ancient-woodland');\n  const hasSSI = envData.some(e=>e.dataset==='site-of-special-scientific-interest');\n\n  const mapPoints = planningData.flatMap(e=>{\n    const p=parsePoint(e.point||'');\n    if (!p||!location) return [];\n    const dist=distanceMiles(location.lat,location.lng,p.lat,p.lng);\n    return [{lat:p.lat,lng:p.lng,type:(e.dataset==='flood-risk-zone'?'flood':e.dataset==='conservation-area'?'conservation':'development') as any,label:e.name||e.dataset,distance:formatDistance(dist)}];\n  });\n\n  return (\n    <>\n      <Head><title>{postcode} area report — StreetPeek</title></Head>\n      <div className={styles.page}>\n        <Navbar />\n        {loading && <div className={styles.loadingWrap}><div className={styles.spinner}/><p>Looking up {postcode}…</p></div>}\n        {error && <div className={styles.errorWrap}><IconAlert size={24} color=\"var(--red)\"/><p>{error}</p></div>}\n        {!loading && !error && location && (<>\n          <div className={styles.header}>\n            <div>\n              <h1 className={styles.postcode}>{location.postcode}</h1>\n              <p className={styles.areaName}>{[location.ward,location.admin_district].filter(Boolean).join(', ')}</p>\n            </div>\n            <div className={styles.scoreWrap}>\n              <div className={styles.scoreLabel}>Area outlook</div>\n              <div className={styles.score}><span className={styles.scoreNum}>{score.toFixed(1)}</span><span className={styles.scoreTag}>{label}</span></div>\n            </div>\n          </div>\n\n          <div className={styles.summary}>\n            <div className={styles.summaryLabel}>Area summary</div>\n            <p>\n              {location.admin_district} —\n              {brownfield.length>0?` ${brownfield.length} brownfield site${brownfield.length>1?'s':''} with housing development within 1 mile.`:' No brownfield housing sites found within 1 mile.'}\n              {totalCrime>0?` ${totalCrime} crimes recorded in the last available month.`:''}\n              {hasFlood?' Flood risk zones present nearby — check before buying.':' No flood risk zones detected.'}\n              {hasConservation?' Area is within or near a conservation zone.':''}\n            </p>\n          </div>\n\n          <div className={styles.tabs}>\n            {([\n              {id:'overview',icon:<IconHouse size={14}/>,label:'Overview'},\n              {id:'planning',icon:<IconBuilding size={14}/>,label:'Planning'},\n              {id:'crime',icon:<IconCrime size={14}/>,label:'Crime'},\n              {id:'environment',icon:<IconWaves size={14}/>,label:'Environment'},\n              {id:'map',icon:<IconMap size={14}/>,label:'Map view'},\n            ] as {id:Tab;icon:React.ReactNode;label:string}[]).map(t=>(\n              <button key={t.id} className={`${styles.tab} ${tab===t.id?styles.tabActive:''}`} onClick={()=>setTab(t.id)}>\n                {t.icon} {t.label}\n              </button>\n            ))}\n          </div>\n\n          {tab==='overview' && (\n            <div className={styles.panel}>\n              <div className={styles.grid}>\n                <div className={styles.card}>\n                  <div className={styles.cardHeader}>\n                    <div className={styles.cardTitle}><IconBuilding size={15} color=\"var(--orange)\"/> Housing developments</div>\n                    <Badge variant={brownfield.length>0?'orange':'neutral'}>{brownfield.length>0?'Active':'None found'}</Badge>\n                  </div>\n                  <div className={styles.bigNum}>{brownfield.length}</div>\n                  <div className={styles.bigSub}>brownfield sites within search radius</div>\n                  {brownfield.length>0&&<p className={styles.cardNote}>Up to {brownfield.reduce((s,e)=>s+parseInt(e.maximum_net_dwellings||'0'),0)} homes across all sites</p>}\n                </div>\n                <div className={styles.card}>\n                  <div className={styles.cardHeader}>\n                    <div className={styles.cardTitle}><IconCrime size={15} color=\"var(--amber)\"/> Crime this month</div>\n                    <Badge variant={totalCrime<50?'good':totalCrime<150?'warn':'red'}>{totalCrime<50?'Low':totalCrime<150?'Moderate':'High'}</Badge>\n                  </div>\n                  <div className={styles.bigNum}>{totalCrime}</div>\n                  <div className={styles.bigSub}>crimes recorded</div>\n                  <div className={styles.bars}>\n                    {crimeData.slice(0,4).map(c=>(\n                      <div key={c.category} className={styles.barRow}>\n                        <span className={styles.barLabel}>{c.category}</span>\n                        <div className={styles.barTrack}><div className={styles.barFill} style={{width:`${(c.count/maxCrime)*100}%`,background:'#FAC775'}}/></div>\n                        <span className={styles.barVal}>{c.count}</span>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n                <div className={styles.card}>\n                  <div className={styles.cardHeader}>\n                    <div className={styles.cardTitle}><IconWaves size={15} color=\"var(--blue)\"/> Flood risk</div>\n                    <Badge variant={hasFlood?'warn':'good'}>{hasFlood?'Risk present':'Low risk'}</Badge>\n                  </div>\n                  <CheckRow ok={!hasFlood}>{hasFlood?'Flood risk zone detected nearby':'No flood risk zones nearby'}</CheckRow>\n                </div>\n                <div className={styles.card}>\n                  <div className={styles.cardHeader}>\n                    <div className={styles.cardTitle}><IconShield size={15} color=\"var(--gray)\"/> Area protections</div>\n                    <Badge variant={hasConservation||hasGreenBelt?'info':'neutral'}>{hasConservation||hasGreenBelt?'Protected':'Unrestricted'}</Badge>\n                  </div>\n                  <CheckRow ok={!hasConservation} neutral>Conservation area: {hasConservation?'Yes':'No'}</CheckRow>\n                  <CheckRow ok={!hasGreenBelt} neutral>Green belt: {hasGreenBelt?'Yes':'No'}</CheckRow>\n                  <CheckRow ok={!hasListedBuildings} neutral>Listed buildings: {hasListedBuildings?'Nearby':'None nearby'}</CheckRow>\n                </div>\n                {brownfield.length>0&&(\n                  <div className={`${styles.card} ${styles.full}`}>\n                    <div className={styles.cardHeader}>\n                      <div className={styles.cardTitle}><IconBuilding size={15} color=\"var(--orange)\"/> Nearby sites</div>\n                      <Badge variant=\"orange\">{brownfield.length} sites</Badge>\n                    </div>\n                    {brownfield.slice(0,4).map((e,i)=>{\n                      const pt=parsePoint(e.point||'');\n                      const dist=pt&&location?formatDistance(distanceMiles(location.lat,location.lng,pt.lat,pt.lng)):'—';\n                      const maxD=parseInt(e.maximum_net_dwellings||'0');\n                      return (\n                        <div key={i} className={styles.devItem}>\n                          <div className={styles.devIcon} style={{background:'var(--orange-light)'}}><IconHouse size={15} color=\"var(--orange)\"/></div>\n                          <div style={{flex:1}}>\n                            <p className={styles.devTitle}>{e.name||'Unnamed site'}</p>\n                            <p className={styles.devMeta}>{maxD>0?`Up to ${maxD} homes`:'Homes TBC'}{dist!=='—'?` · ${dist} away`:''}{e.hectares?` · ${e.hectares} ha`:''}</p>\n                          </div>\n                          <Badge variant={e.planning_permission_status==='permissioned'?'good':'warn'}>{e.planning_permission_status==='permissioned'?'Approved':e.planning_permission_status||'Unknown'}</Badge>\n                        </div>\n                      );\n                    })}\n                  </div>\n                )}\n              </div>\n              <UnlockBanner />\n            </div>\n          )}\n\n          {tab==='planning' && (\n            <div className={styles.panel}>\n              <p className={styles.tabIntro}><IconDocument size={15} color=\"var(--orange)\"/>&nbsp;Showing free preview — {Math.min(brownfield.length+applications.length,3)} of {brownfield.length+applications.length} results.{' '}<a href=\"/pricing\" className={styles.orangeLink}>Unlock all →</a></p>\n              <div className={styles.card} style={{marginBottom:'1rem'}}>\n                {[...brownfield,...applications].slice(0,3).map((e,i)=>{\n                  const pt=parsePoint(e.point||'');\n                  const dist=pt&&location?formatDistance(distanceMiles(location.lat,location.lng,pt.lat,pt.lng)):null;\n                  return (\n                    <div key={i} className={styles.devItem}>\n                      <div className={styles.devIcon} style={{background:'var(--orange-light)'}}><IconHouse size={15} color=\"var(--orange)\"/></div>\n                      <div style={{flex:1}}>\n                        <p className={styles.devTitle}>{e.name||'Planning application'}</p>\n                        <p className={styles.devMeta}>{e.dataset} · {e.start_date||'Date unknown'}{dist?` · ${dist} away`:''}</p>\n                      </div>\n                      <Badge variant={e.planning_permission_status==='permissioned'?'good':'neutral'}>{e.planning_permission_status||'Unknown'}</Badge>\n                    </div>\n                  );\n                })}\n                {brownfield.length+applications.length===0&&<p className={styles.emptyMsg}>No planning applications found. Coverage varies by council.</p>}\n              </div>\n              <UnlockBanner />\n            </div>\n          )}\n\n          {tab==='crime' && (\n            <div className={styles.panel}>\n              <div className={styles.card}>\n                <div className={styles.cardHeader}>\n                  <div className={styles.cardTitle}><IconCrime size={15} color=\"var(--amber)\"/> Crime by category</div>\n                  <Badge variant={totalCrime<50?'good':totalCrime<150?'warn':'red'}>{totalCrime} total</Badge>\n                </div>\n                {crimeData.length===0&&<p className={styles.emptyMsg}>No crime data available for this area.</p>}\n                {crimeData.map(c=>(\n                  <div key={c.category} className={styles.barRow} style={{marginBottom:'10px'}}>\n                    <span className={styles.barLabel}>{c.category}</span>\n                    <div className={styles.barTrack}><div className={styles.barFill} style={{width:`${(c.count/maxCrime)*100}%`,background:'#FAC775'}}/></div>\n                    <span className={styles.barVal}>{c.count}</span>\n                  </div>\n                ))}\n                <p className={styles.dataSource}><IconCalendar size={13} color=\"var(--text-tertiary)\"/> Source: data.police.uk · 3-year trend charts in full report</p>\n              </div>\n              <UnlockBanner />\n            </div>\n          )}\n\n          {tab==='environment' && (\n            <div className={styles.panel}>\n              <div className={styles.grid}>\n                <div className={styles.card}>\n                  <div className={styles.cardHeader}><div className={styles.cardTitle}><IconWaves size={15} color=\"var(--blue)\"/> Flood risk</div><Badge variant={hasFlood?'warn':'good'}>{hasFlood?'Risk present':'Low risk'}</Badge></div>\n                  <CheckRow ok={!hasFlood}>{hasFlood?'Flood risk zone present':'No flood risk zones within radius'}</CheckRow>\n                </div>\n                <div className={styles.card}>\n                  <div className={styles.cardHeader}><div className={styles.cardTitle}><IconShield size={15} color=\"var(--gray)\"/> Designations</div></div>\n                  <CheckRow ok={!hasConservation} neutral>Conservation area: {hasConservation?'Yes':'No'}</CheckRow>\n                  <CheckRow ok={!hasGreenBelt} neutral>Green belt: {hasGreenBelt?'Yes':'No'}</CheckRow>\n                  <CheckRow ok={!hasAncientWoodland} neutral>Ancient woodland: {hasAncientWoodland?'Yes':'No'}</CheckRow>\n                  <CheckRow ok={!hasSSI} neutral>SSSI: {hasSSI?'Yes':'No'}</CheckRow>\n                  <CheckRow ok={!hasListedBuildings} neutral>Listed buildings: {hasListedBuildings?'Nearby':'None nearby'}</CheckRow>\n                </div>\n              </div>\n              <UnlockBanner />\n            </div>\n          )}\n\n          {tab==='map' && (\n            <div className={styles.panel}>\n              <p className={styles.tabIntro}><IconMap size={15} color=\"var(--orange)\"/>&nbsp;Free view: 0.3 mile radius. <a href=\"/pricing\" className={styles.orangeLink}>Unlock 2-mile view →</a></p>\n              <AreaMap lat={location.lat} lng={location.lng} points={mapPoints} locked={true} freeRadiusMiles={0.3}/>\n            </div>\n          )}\n        </>)}\n      </div>\n    </>\n  );\n}\n\nfunction CheckRow({ok,neutral=false,children}:{ok?:boolean;neutral?:boolean;children:React.ReactNode}) {\n  return (\n    <div style={{display:'flex',alignItems:'flex-start',gap:10,padding:'7px 0',borderBottom:'0.5px solid var(--border)'}}>\n      {ok ? <IconTick size={18} color=\"var(--green)\"/> : <IconCross size={18} color={neutral?'var(--gray)':'var(--amber)'}/>}\n      <span style={{fontSize:13,lineHeight:1.4}}>{children}</span>\n    </div>\n  );\n}\n\nfunction UnlockBanner() {\n  return (\n    <div style={{marginTop:'1.5rem',padding:'1.25rem',border:'0.5px solid var(--border-mid)',borderRadius:'var(--radius-lg)',background:'var(--bg-secondary)',textAlign:'center'}}>\n      <h4 style={{fontSize:14,fontWeight:500,marginBottom:6}}>Get the full picture</h4>\n      <p style={{fontSize:13,color:'var(--text-secondary)',marginBottom:14,lineHeight:1.55}}>Unlock all planning applications with reference numbers, 3-year crime charts, a 2-mile map with every data layer, and a PDF to share with your solicitor.</p>\n      <div style={{display:'flex',flexWrap:'wrap',gap:6,justifyContent:'center',marginBottom:14}}>\n        {['All planning docs','3-year crime charts','2mi map view','PDF report','Email alerts'].map(f=>(\n          <span key={f} style={{fontSize:12,background:'var(--bg)',border:'0.5px solid var(--border)',borderRadius:'999px',padding:'4px 12px',color:'var(--text-secondary)'}}>{f}</span>\n        ))}\n      </div>\n      <a href=\"/pricing\" style={{display:'inline-block',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-md)',padding:'10px 28px',fontSize:14,fontWeight:500,textDecoration:'none'}}>Get full report — £4.99</a>\n      <p style={{fontSize:12,color:'var(--text-tertiary)',marginTop:8}}>One-time payment · Instant PDF · No subscription needed</p>\n    </div>\n  );\n}",
  "streetpeek/pages/_document.tsx": "import { Html, Head, Main, NextScript } from 'next/document';\nexport default function Document() {\n  return (\n    <Html lang=\"en\">\n      <Head>\n        <meta charSet=\"utf-8\" />\n        <link rel=\"icon\" href=\"/favicon.ico\" />\n        <meta name=\"description\" content=\"See what's coming to your street — planning applications, crime trends, flood risk and new developments before you buy.\" />\n      </Head>\n      <body><Main /><NextScript /></body>\n    </Html>\n  );\n}",
  "streetpeek/pages/_app.tsx": "import type { AppProps } from 'next/app';\nimport '../styles/globals.css';\nimport 'leaflet/dist/leaflet.css';\nexport default function App({ Component, pageProps }: AppProps) {\n  return <Component {...pageProps} />;\n}",
  "streetpeek/pages/pricing.tsx": "import Head from 'next/head';\nimport Navbar from '../components/Navbar';\nimport styles from '../styles/Pricing.module.css';\n\nconst plans = [\n  { name:'Free', price:'£0', desc:'Get a feel for any area instantly.', features:['Basic crime headline','1 brownfield site result','0.3mi map view','Area summary'], cta:'Start searching', href:'/', highlight:false },\n  { name:'Full report', price:'£4.99', desc:'One-time payment. Everything for one postcode.', features:['All planning applications','Full brownfield + infrastructure data','2mi interactive map','12-month crime breakdown','Flood & environment detail','PDF to share with solicitor'], cta:'Buy report', href:'/', highlight:true },\n  { name:'Pro', price:'£9.99/mo', desc:'For active buyers and investors.', features:['Unlimited postcode searches','Email alerts for new applications','All full report features','Save and compare areas'], cta:'Coming soon', href:'#', highlight:false },\n];\n\nexport default function Pricing() {\n  return (\n    <>\n      <Head><title>Pricing — StreetPeek</title></Head>\n      <div className={styles.page}>\n        <Navbar />\n        <div className={styles.hero}>\n          <h1 className={styles.headline}>Simple, transparent pricing</h1>\n          <p className={styles.sub}>Start free. Pay only when you need the full picture.</p>\n        </div>\n        <div className={styles.grid}>\n          {plans.map(plan=>(\n            <div key={plan.name} className={`${styles.card} ${plan.highlight?styles.highlight:''}`}>\n              {plan.highlight&&<div className={styles.badge}>Most popular</div>}\n              <div className={styles.planName}>{plan.name}</div>\n              <div className={styles.price}>{plan.price}</div>\n              <p className={styles.desc}>{plan.desc}</p>\n              <ul className={styles.features}>\n                {plan.features.map(f=>(\n                  <li key={f}>\n                    <svg width=\"14\" height=\"14\" viewBox=\"0 0 16 16\" fill=\"none\"><circle cx=\"8\" cy=\"8\" r=\"6.5\" stroke={plan.highlight?'var(--orange)':'var(--green)'} strokeWidth=\"1.3\"/><path d=\"M5.5 8.5L7 10L10.5 6.5\" stroke={plan.highlight?'var(--orange)':'var(--green)'} strokeWidth=\"1.3\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>\n                    {f}\n                  </li>\n                ))}\n              </ul>\n              <a href={plan.href} className={`${styles.cta} ${plan.highlight?styles.ctaHighlight:''}`}>{plan.cta}</a>\n            </div>\n          ))}\n        </div>\n      </div>\n    </>\n  );\n}",
  "streetpeek/pages/index.tsx": "import Head from 'next/head';\nimport Navbar from '../components/Navbar';\nimport PostcodeSearch from '../components/PostcodeSearch';\nimport { IconBuilding, IconWaves, IconMap, IconShield, IconTrend, IconHouse } from '../components/icons';\nimport styles from '../styles/Home.module.css';\n\nexport default function Home() {\n  return (\n    <>\n      <Head><title>StreetPeek — See what's coming to your street</title></Head>\n      <div className={styles.page}>\n        <Navbar />\n        <section className={styles.hero}>\n          <div className={styles.eyebrow}>UK property intelligence</div>\n          <h1 className={styles.headline}>See what's coming to<br /><em>your street</em></h1>\n          <p className={styles.subhead}>Planning applications, new developments, crime trends and more — all in one place, before you buy.</p>\n          <div className={styles.searchWrap}><PostcodeSearch large /></div>\n          <div className={styles.pills}>\n            {['Planning applications','Housing developments','Crime statistics','Flood risk','Conservation areas','Brownfield sites','Interactive map'].map(label => (\n              <span key={label} className={styles.pill}>{label}</span>\n            ))}\n          </div>\n        </section>\n\n        <section className={styles.features}>\n          <div className={styles.featureCard}>\n            <div className={styles.featureIcon} style={{background:'var(--orange-light)'}}><IconBuilding size={20} color=\"var(--orange)\" /></div>\n            <h3>Planning data</h3>\n            <p>Every approved and pending development within 1 mile of any postcode, mapped and explained in plain English.</p>\n          </div>\n          <div className={styles.featureCard}>\n            <div className={styles.featureIcon} style={{background:'var(--blue-light)'}}><IconWaves size={20} color=\"var(--blue)\" /></div>\n            <h3>Flood &amp; environment</h3>\n            <p>Flood risk zones, conservation areas, green belt and tree preservation orders — all constraints that affect development.</p>\n          </div>\n          <div className={styles.featureCard}>\n            <div className={styles.featureIcon} style={{background:'var(--orange-light)'}}><IconTrend size={20} color=\"var(--orange)\" /></div>\n            <h3>Crime trends</h3>\n            <p>12-month crime data by category, compared to the national average with a clear trend direction.</p>\n          </div>\n          <div className={styles.featureCard}>\n            <div className={styles.featureIcon} style={{background:'var(--green-light)'}}><IconHouse size={20} color=\"var(--green)\" /></div>\n            <h3>Brownfield sites</h3>\n            <p>Former industrial land approved for housing — see exactly how many homes are planned and when.</p>\n          </div>\n          <div className={styles.featureCard}>\n            <div className={styles.featureIcon} style={{background:'var(--gray-light)'}}><IconShield size={20} color=\"var(--gray)\" /></div>\n            <h3>Area protections</h3>\n            <p>Conservation areas, listed buildings and green belt — factors that restrict development and protect character.</p>\n          </div>\n          <div className={styles.featureCard}>\n            <div className={styles.featureIcon} style={{background:'var(--orange-light)'}}><IconMap size={20} color=\"var(--orange)\" /></div>\n            <h3>Interactive map</h3>\n            <p>Every data point on a live map. Free view: 0.3 miles. Full report: 2-mile radius with all layers togglable.</p>\n          </div>\n        </section>\n\n        <div className={styles.mapTeaser}>\n          <div className={styles.mapTeaserLabel}><span className={styles.mapTeaserDot} />Interactive map on every search</div>\n          <div className={styles.mapTeaserVisual}>\n            <div className={styles.mapTeaserGrid} />\n            <div className={styles.mapTeaserContent}>\n              <div className={styles.mapPin}><div className={styles.mapPinInner} /></div>\n              <div className={styles.mapRipple} /><div className={styles.mapRipple2} />\n              <div className={styles.mapTeaserChip} style={{top:'-36px',left:'32px'}}><IconBuilding size={12} color=\"var(--orange)\" />&nbsp;480 homes · 0.1mi</div>\n              <div className={styles.mapTeaserChip} style={{top:'28px',left:'-120px'}}><IconWaves size={12} color=\"var(--blue)\" />&nbsp;Flood zone · 0.4mi</div>\n            </div>\n            <p className={styles.mapTeaserHint}>Free: 0.3mi view &nbsp;·&nbsp; Full report: 2mi radius with all layers</p>\n          </div>\n        </div>\n\n        <footer className={styles.trustBar}>\n          {['planning.data.gov.uk','data.police.uk','Environment Agency','Updated weekly','Open Government Licence'].map(item => (\n            <div key={item} className={styles.trustItem}><span className={styles.trustDot} />{item}</div>\n          ))}\n        </footer>\n      </div>\n    </>\n  );\n}"
};

let created = 0;
for (const [rel, content] of Object.entries(files)) {
  const full = path.join(process.cwd(), rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content, 'utf8');
  console.log('  created', rel);
  created++;
}
console.log('\nDone! ' + created + ' files created.');
console.log('\nNext steps:');
console.log('  cd streetpeek');
console.log('  npm install');
console.log('  npm run dev');
console.log('\nThen open http://localhost:3000');
